// One keyboard behaviour for every panel and sidebar list: the pure decisions (no herdr import, so bun tests them).
// Source of truth: shared/; each mod's copy is generated by scripts/sync-shared.sh and checked in CI. Don't edit a copy.

const FRESH = 3000; // a signal older than this was meant for someone before us

// The state a copy starts from: whatever signals are already there were meant for someone else.
export function seed(sig) {
  return { openedAt: sig.opened?.at ?? null, backAt: sig.back ?? null, ovAt: sig.over?.at ?? null, resume: false, prevHeld: !!sig.held };
}

// One frame: sig = { id, panel, shown, held, opened: {id, at}?, back: at?, over: {at, open, went?}? }.
// Returns the next state and whether to focus: after ms, and "no-dialog" when the wiring must first check that no
// dialog is open again (a menu closing straight into a confirm).
//  - opened: tabs-plus opened this panel on purpose (⌘⇧E, its tab) -> take the keyboard.
//  - back: a panel's own window or popup closed -> the side panel showing takes it (panels only).
//  - over: a dialog took the keyboard from here (held the frame before it opened) and closed without moving you on.
// A hidden panel neither acts on nor consumes opened/back: shown later, a fresh one still counts.
export function decide(state, sig, now) {
  let next = { ...state }, focus = null;
  if (sig.panel && sig.shown) {
    const o = sig.opened;
    if (o && o.at !== state.openedAt) {
      next.openedAt = o.at;
      if (o.id === sig.id && now - o.at < FRESH) focus = { after: 50, check: "none" };
    }
    if (sig.back && sig.back !== state.backAt) {
      next.backAt = sig.back;
      if (now - sig.back < FRESH) focus ??= { after: 80, check: "none" };
    }
  }
  const ov = sig.over;
  if (ov && ov.at !== state.ovAt) {
    next.ovAt = ov.at;
    if (ov.open) next.resume = state.resume || state.prevHeld;
    else if (state.resume && ov.went) next.resume = false;
    else if (state.resume) focus ??= { after: 80, check: "no-dialog" }; // resume stays until settle(): a confirm may follow
  }
  next.prevHeld = !!sig.held;
  return { state: next, focus };
}

// After a dialog-return's wait found no dialog open again: the way back is used up.
export const settle = (state) => ({ ...state, resume: false });

// Vim keys in a list: h/j/k/l as ←/↓/↑/→, never while typing in a field.
export function listKey(k, typing) {
  return typing ? k : ({ h: "left", j: "down", k: "up", l: "right" }[k] ?? k);
}
